using AutoMapper;
using EmployeeEvaluationSystem.DTOs;
using EmployeeEvaluationSystem.Helpers;
using EmployeeEvaluationSystem.Repositories;

namespace EmployeeEvaluationSystem.Services;

/// <summary>Read/mark-as-read access to the caller's own in-app notifications, generated by every workflow stage across the system.</summary>
public class NotificationService : INotificationService
{
    private readonly INotificationRepository _notificationRepository;
    private readonly IMapper _mapper;

    public NotificationService(INotificationRepository notificationRepository, IMapper mapper)
    {
        _notificationRepository = notificationRepository;
        _mapper = mapper;
    }

    public async Task<List<NotificationDto>> GetAllAsync(int userId)
    {
        var notifications = await _notificationRepository.GetByUserAsync(userId);
        return _mapper.Map<List<NotificationDto>>(notifications);
    }

    public async Task<List<NotificationDto>> GetUnreadAsync(int userId)
    {
        var notifications = await _notificationRepository.GetUnreadByUserAsync(userId);
        return _mapper.Map<List<NotificationDto>>(notifications);
    }

    public async Task<NotificationDto> MarkAsReadAsync(int userId, int notificationId)
    {
        var notification = await _notificationRepository.GetByIdAsync(notificationId)
            ?? throw new NotFoundException("Notification", notificationId);

        if (notification.UserId != userId)
        {
            throw new ForbiddenException("You can only mark your own notifications as read.");
        }

        notification.IsRead = true;
        await _notificationRepository.UpdateAsync(notification);
        await _notificationRepository.SaveChangesAsync();

        return _mapper.Map<NotificationDto>(notification);
    }

    public async Task MarkAllAsReadAsync(int userId)
    {
        await _notificationRepository.MarkAllAsReadAsync(userId);
        await _notificationRepository.SaveChangesAsync();
    }
}
